#[test]
fn reads_bootstrap() {
    let mut only_path = HashMap::new();
    only_path.insert("GROW_SECRETS_PATH".to_string(), "x".to_string());
    assert!(read_secrets_bootstrap(Some(&only_path)).unwrap().is_none());
    let b = read_secrets_bootstrap(Some(&boot())).unwrap().unwrap();
    assert_eq!(b.path, "services/orders");
    assert_eq!(b.auth, "approle");
    assert_eq!(b.kv_mount.as_deref(), Some("kv"));
    assert_eq!(b.role_id.as_ref().unwrap().expose_secret(), "role-1");
    assert!(!format!("{b:?}").contains("secret-1"));
    let mut bad = HashMap::new();
    bad.insert("GROW_SECRETS_ADDR".to_string(), "a".to_string());
    bad.insert("GROW_SECRETS_AUTH".to_string(), "approle".to_string());
    assert_eq!(
        read_secrets_bootstrap(Some(&bad)).unwrap_err().code(),
        ErrorCode::Config
    );
}

#[tokio::test]
async fn loads_from_provider() {
    let p = memory().await;
    let mut env = HashMap::new();
    env.insert("B".to_string(), "x".to_string());
    let mut o = opts(env);
    o.required = vec!["DATABASE_URL".into()];
    let values = load_config_from(p.as_ref(), "services/orders", &o)
        .await
        .unwrap();
    assert_eq!(values["DATABASE_URL"], "postgres://db");
    assert_eq!(values["LOG_LEVEL"], "debug");
    assert_eq!(values.len(), 3);
    o.required = vec!["A".into(), "B".into(), "C".into()];
    let err = load_config_from(p.as_ref(), "services/orders", &o)
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::NotFound);
    assert!(err.to_string().contains("A, C"));
    assert!(err.to_string().contains("\"services/orders\""));
}

#[tokio::test]
async fn sets_process_env() {
    let p = InMemorySecretsProvider::new();
    p.set("SDKKIT_LOAD_CONFIG_RS", "v".into(), None)
        .await
        .unwrap();
    p.set("SDKKIT_LOAD_CONFIG_RS_KEEP", "new".into(), None)
        .await
        .unwrap();
    p.set("GROW_SECRETS_SDKKIT", "no".into(), None)
        .await
        .unwrap();
    std::env::set_var("SDKKIT_LOAD_CONFIG_RS_KEEP", "old");
    let o = LoadOptions {
        keep_existing: true,
        ..LoadOptions::default()
    };
    load_config_from(&p, "", &o).await.unwrap();
    assert_eq!(std::env::var("SDKKIT_LOAD_CONFIG_RS").unwrap(), "v");
    assert_eq!(std::env::var("SDKKIT_LOAD_CONFIG_RS_KEEP").unwrap(), "old");
    assert!(std::env::var("GROW_SECRETS_SDKKIT").is_err());
}

fn connector(path: Option<&'static str>, closed: Arc<AtomicUsize>) -> SecretsConnector {
    Arc::new(move |_b: SecretsBootstrap, _env| {
        let closed = closed.clone();
        async move {
            let provider: Arc<dyn SecretsProvider> = memory().await;
            Ok(SecretsConnection {
                provider,
                path: path.map(str::to_string),
                close: Some(
                    async move {
                        closed.fetch_add(1, Ordering::SeqCst);
                    }
                    .boxed(),
                ),
            })
        }
        .boxed()
    })
}

#[tokio::test]
async fn loads_with_connector() {
    let closed = Arc::new(AtomicUsize::new(0));
    let mut o = opts(boot());
    o.required = vec!["DATABASE_URL".into()];
    o.connector = Some(connector(None, closed.clone()));
    let values = load_config(o.clone()).await.unwrap();
    assert_eq!(values["DATABASE_URL"], "postgres://db");
    o.required = vec!["NOPE".into()];
    assert_eq!(
        load_config(o).await.unwrap_err().code(),
        ErrorCode::NotFound
    );
    assert_eq!(closed.load(Ordering::SeqCst), 2);
    let mut other = opts(boot());
    other.connector = Some(connector(Some("services/other"), closed.clone()));
    let values = load_config(other.clone()).await.unwrap();
    assert_eq!(values.get("X").map(String::as_str), Some("no"));
    other.path = Some("services/orders".into());
    assert!(load_config(other)
        .await
        .unwrap()
        .contains_key("DATABASE_URL"));
    assert!(format!("{:?}", LoadOptions::default()).contains("into_env: true"));
}

